lab.solution:
import re

def valid_course_code(text):
    pattern = r'[A-Z]{2}-[0-9]{3}'
    return re.fullmatch(pattern, text) is not None

for value in ['PY-101', 'py-101', 'PY-101-extra']:
    print(value, valid_course_code(value))
